box = {"M3 screws": 40, "M2 screws": 12, "#6-32 screws": 30, "standoffs": 18,
       "washers": 25, "jumpers": 10, "thermal pads": 8}
print("Grid box inventory:")
for item, qty in box.items():
    print(f"  {qty:>3} x {item}")
print(f"Compartments used: {len(box)} | total pieces: {sum(box.values())}")

lib = {"M3x5": 22, "M3x8": 14, "#6-32x1/4": 31, "#6-32x3/8": 9, "M2x3": 11}
print("Screw library (sorted by thread x length):")
for k, v in lib.items():
    print(f"  {k:<10} {v} pcs")
print("Rule: sort by SPEC, not by origin. Gauge card in lid IDs mystery screws.")

stage = {"standoffs M3": 9, "board M3x5": 9, "PSU #6-32": 4, "M.2 M2x3": 2, "fan": 8}
print("Build staging (active box):")
for k, v in stage.items():
    print(f"  [{k:<14}] {v} pcs")
print("End of build: every compartment empty = every screw placed.")

nodes = 4
per_node = {"standoffs": 9, "board screws": 9, "drive screws": 6}
print(f"{nodes}-node staging: one compartment per node per type")
for n in range(1, nodes + 1):
    print(f"  node {n}: " + ", ".join(f"{v}x {k}" for k, v in per_node.items()))
print("Lid closed for transport; photo the box before leaving the bench.")

mins = {"M3x5": 10, "#6-32x1/4": 10, "M2x3": 6, "standoffs": 6}
have = {"M3x5": 22, "#6-32x1/4": 7, "M2x3": 11, "standoffs": 18}
print("Kanban check:")
for k, m in mins.items():
    status = "OK" if have[k] >= m else "ORDER"
    print(f"  {k:<12} have {have[k]:>2}, min {m:>2} -> {status}")
